"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5243],{97620:n=>{n.exports=JSON.parse('{"functions":[{"name":"post","desc":"Writes values to the output log. Analog of C `printf` / Luau `print`.\\n\\n**Syntax:** `void post(...);`\\n\\n**Return:** `void`\\n\\n**Emit:** `print(...)`\\n\\n```clpp\\npost(\\"hello\\");\\npost(\\"coins:\\", 100);\\npost(\\"online: \\" .: players.GetPlayers());\\n```","params":[{"name":"...","desc":"Values to print","lua_type":"any"}],"returns":[],"function_type":"static","tags":["io"],"source":{"line":30,"path":"moonwave/Builtins.lua"}},{"name":"warn","desc":"Yellow warning. Does not stop the thread.\\n\\n**Syntax:** `void warn(...);`\\n\\n**Emit:** `warn(...)`\\n\\nPair with `guard` when the failure is expected.","params":[{"name":"...","desc":"Warning payload","lua_type":"any"}],"returns":[],"function_type":"static","tags":["io"],"source":{"line":45,"path":"moonwave/Builtins.lua"}},{"name":"report","desc":"Throws. Analog of C++ `throw` / Luau `error`. The current thread stops.\\n\\n**Syntax:** `void report(...);`\\n\\n**Return:** does not return\\n\\n**Emit:** `error(...)`\\n\\nThere is no `try/catch`. Catch with `pcall`.","params":[{"name":"...","desc":"Error payload","lua_type":"any"}],"returns":[],"function_type":"static","tags":["io"],"source":{"line":62,"path":"moonwave/Builtins.lua"}},{"name":"GetService<T>","desc":"Looks up a Roblox service by class name. The only generic besides collections and `static_cast`.\\n\\n**Syntax:** `T GetService<T>();`\\n\\n**Return:** Instance of class `T`\\n\\n**Emit:** `game:GetService(\\"T\\")`\\n\\n```clpp\\nPlayers players = GetService<Players>();\\n```\\n\\nThere is no `game:GetService` in CL++ source.","params":[],"returns":[],"function_type":"static","source":{"line":82,"path":"moonwave/Builtins.lua"}},{"name":"pcall","desc":"Protected call. CL++ has no `try/catch`.\\n\\n**Syntax:** `auto [ok, result] = pcall(fn);`\\n\\n**Return:** success flag, then result or error string\\n\\n**Emit:** `pcall(fn)`","params":[{"name":"fn","desc":"Callback to run","lua_type":"func"}],"returns":[],"function_type":"static","source":{"line":95,"path":"moonwave/Builtins.lua"}},{"name":"new","desc":"Constructs a Roblox Instance or a library object. Not C++ heap allocation \u2014 there is no `delete`.\\n\\n**Syntax:** `auto child = new Class(parent);`\\n\\n**Emit:** `Instance.new(\\"Class\\")` for Instances (first arg \u2192 `.Parent`); `Janitor.new()` for libs.\\n\\nDatatypes (`Vector3`, `CFrame`) are values: write `Vector3(8, 1, 8)`, not `new Vector3`.","params":[],"returns":[],"function_type":"static","tags":["constructor"],"source":{"line":109,"path":"moonwave/Builtins.lua"}},{"name":"static_cast","desc":"Source-level type annotation. Luau has no runtime casts \u2014 this does not check `ClassName`.\\n\\n**Syntax:** `T static_cast<T>(value);`\\n\\n**Emit:** `value` with a Luau annotation\\n\\nUse `match` to branch on Instance class at runtime.","params":[{"name":"value","desc":"Expression to re-annotate","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":123,"path":"moonwave/Builtins.lua"}},{"name":"string_concat","desc":"Variadic string join. Prefer `.:` for two operands.\\n\\n**Syntax:** `string string_concat(...);`\\n\\n**Return:** `string`. Zero args \u2192 `\\"\\"`. One arg \u2192 that value.\\n\\n**Emit:** `(a .. b .. c)`\\n\\nDo not write Lua `..` and do not use `+` on strings.","params":[{"name":"...","desc":"Values to join","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":139,"path":"moonwave/Builtins.lua"}},{"name":"to_string","desc":"Convert any value to text. Analog of C++ `std::to_string` / Luau `tostring`.\\n\\n**Syntax:** `string to_string(value);`\\n\\n**Emit:** `tostring(value)`\\n\\nDo not write Luau `tostring` in CL++ source.","params":[{"name":"value","desc":"Value to convert","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":153,"path":"moonwave/Builtins.lua"}},{"name":"to_number","desc":"Parse a number from text (or pass a number through). Analog of `std::stod` / Luau `tonumber`.\\n\\n**Syntax:** `float to_number(value);` \xb7 `float to_number(value, base);`\\n\\n**Emit:** `tonumber(value)`\\n\\nFails \u2192 `null`. Do not write Luau `tonumber` in CL++ source.","params":[{"name":"value","desc":"Text or number","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":167,"path":"moonwave/Builtins.lua"}},{"name":"to_bool","desc":"Coerce to boolean. Anything truthy becomes `true`.\\n\\n**Syntax:** `bool to_bool(value);`\\n\\n**Emit:** `not not (value)`","params":[{"name":"value","desc":"Value to coerce","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":179,"path":"moonwave/Builtins.lua"}},{"name":"null","desc":"Absence of a value. `nullptr` is a synonym.\\n\\n**Syntax:** `Player ref = null;`\\n\\n**Emit:** `nil`\\n\\nUninitialized locals (`int coins;`) also emit `nil` \u2014 always initialize.","params":[],"returns":[],"function_type":"static","source":{"line":192,"path":"moonwave/Builtins.lua"}},{"name":"init","desc":"Script / LocalScript entry. There is no `int main()`.\\n\\n**Syntax:** `void init() { }`\\n\\n**Emit:** `init()` called at the end of the file\\n\\nConstruct one service object in `init()` and close over it from lambdas.","params":[],"returns":[],"function_type":"static","source":{"line":205,"path":"moonwave/Builtins.lua"}}],"properties":[],"types":[],"name":"Builtins","desc":"Global functions that exist in every CL++ program. You do not import these.\\n\\nEach entry below is a full reference: syntax, parameters, return value, Luau emit, and example.\\nThe header-style index is [Language reference](/CLPP/docs/reference).","source":{"line":10,"path":"moonwave/Builtins.lua"}}')}}]);